// Traduce el primer objeto del recuerdo a las columnas de entrada del
// clasificador entrenado (Backend/ml/model_recomendacion.py). uso_deseado,
// presupuesto, ciudad y preferencia todavia no se capturan en el registro
// de un recuerdo, asi que usan un valor neutro documentado (ver
// fila_desde_objeto_memoria en ese mismo modulo) en vez de inventarlos.
const recuerdo = $('Obtener recuerdo').item.json;
const objetos = recuerdo.objetos || [];
const primero = objetos[0] || {};
const cantidad = objetos.length || 1;

function match(valor, opciones, defecto) {
  const v = (valor || '').toString().toLowerCase();
  for (const op of opciones) { if (v.includes(op)) return op; }
  return defecto;
}

const body = {
  tipo_objeto: match(primero.tipo, ['peluche', 'prenda_textil', 'fotografia', 'joya_pequena', 'carta_documento', 'mueble', 'reloj_instrumento'], 'otro_objeto'),
  material: match(primero.material, ['tela', 'papel', 'madera', 'metal', 'vidrio', 'peluche_sintetico', 'cuero', 'mixto'], 'mixto'),
  estado: match(primero.estado, ['bueno', 'regular', 'danado', 'muy_danado'], 'regular'),
  transformacion: match(primero.nivel_transformacion, ['ninguna', 'leve', 'moderada', 'total'], 'leve'),
  cantidad,
  uso_deseado: 'conservar',
  presupuesto: 95000,
  ciudad: 'Bogota',
  preferencia: 'fisico',
};

return [{ json: { mlBodyString: JSON.stringify(body) } }];

const recuerdo = $('Obtener recuerdo').item.json;
const catalogoRaw = $('Obtener catalogo').item.json.results || [];
const catalogo = catalogoRaw.filter((p) => p.activo).map((p) => ({
  id: Number(p.id),
  nombre: p.nombre,
  categoria: p.categoria,
  descripcion: p.descripcion,
}));

// Senal del clasificador entrenado (arbol de decision, Backend/ml/) sobre
// el primer objeto del recuerdo. Si el servicio de ML falla o no responde
// (onError continueRegularOutput en 'Consultar modelo ML'), senalMl queda
// null y el prompt simplemente no la menciona -- no bloquea la recomendacion.
const mlResp = $('Consultar modelo ML').item.json;
const senalMl = mlResp && mlResp.producto_recomendado
  ? { producto: mlResp.producto_recomendado, probabilidad: mlResp.probabilidad }
  : null;

// Este prompt cubre en un solo paso lo que la arquitectura describe como
// tres agentes: Creativo (concepto_creativo), Viabilidad (advertencias /
// requiere_revision_humana) y Recomendacion (puntaje, ranking).
let systemPrompt = `Eres el equipo de Creativo, Viabilidad y Recomendacion de Reviive, un taller de restauracion de objetos con valor emocional. Recibiras la historia de un recuerdo/objeto de un cliente y el catalogo de servicios disponibles (cada uno con un id numerico). Responde UNICAMENTE con un JSON con esta forma exacta: {"recomendaciones": [{"producto_id": <id entero que exista en el catalogo dado>, "titulo": <string corto>, "concepto_creativo": <1-2 frases, propuesta creativa personalizada y especifica para ESTE objeto y esta historia>, "puntaje": <numero entre 0 y 1, que tan bien se ajusta>, "advertencias": [<string, riesgos o restricciones tecnicas del material/estado, o vacio si no hay>], "requiere_revision_humana": <true o false>}]}. Elige como maximo 3 productos del catalogo que mejor se ajusten, ordenados por puntaje descendente. Marca requiere_revision_humana=true si la transformacion implica cortar, desarmar o desechar parte del material original (en ese caso el cliente debe autorizarlo explicitamente antes de proceder), o si el estado descrito sugiere que el objeto necesita inspeccion presencial antes de cualquier compromiso. Nunca inventes un producto_id que no este en el catalogo. concepto_creativo es una sugerencia, nunca confirmes precios ni tiempos de entrega exactos (eso lo define el taller en una cotizacion formal).`;

if (senalMl) {
  systemPrompt += ` Un modelo de machine learning (arbol de decision entrenado con datos de casos similares) sugiere como servicio mas probable para este tipo de objeto: "${senalMl.producto}" (confianza ${Math.round(senalMl.probabilidad * 100)}%). Considera esta senal como una opinion experta mas, no la sigas ciegamente si la historia concreta del cliente sugiere algo distinto: prioriza siempre lo que cuenta la historia real por encima de la sugerencia estadistica.`;
}

const userPayload = {
  recuerdo: {
    historia: recuerdo.historia,
    objetos: (recuerdo.objetos || []).map((o) => ({
      tipo: o.tipo, marca: o.marca, anio_aproximado: o.anio_aproximado,
      material: o.material, estado: o.estado,
    })),
  },
  catalogo,
};

return [{
  json: {
    recuerdo_id: $('Webhook').item.json.body.recuerdo_id,
    run_id: $('Registrar inicio de agente').item.json.run_id,
    senalMl,
    openaiPayload: {
      model: 'gpt-4o-mini',
      response_format: { type: 'json_object' },
      temperature: 0.4,
      max_tokens: 700,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: JSON.stringify(userPayload) },
      ],
    },
  },
}];

const resp = $json;
let recomendaciones = [];
let estado = 'fallido';

try {
  if (!resp.error && resp.choices && resp.choices.length) {
    const parsed = JSON.parse(resp.choices[0].message.content);
    if (Array.isArray(parsed.recomendaciones)) {
      recomendaciones = parsed.recomendaciones;
      estado = 'completado';
    }
  }
} catch (e) {
  estado = 'fallido';
}

return [{
  json: {
    recuerdo_id: $('Preparar prompt recomendacion').item.json.recuerdo_id,
    run_id: $('Preparar prompt recomendacion').item.json.run_id,
    estado,
    recomendaciones,
  },
}];

const senalMl = $('Preparar prompt recomendacion').item.json.senalMl;
const body = {
  status: $json.estado,
  structured_data: {
    recuerdo_id: $json.recuerdo_id,
    recomendaciones: $json.recomendaciones,
    // Se deja registrada la senal del modelo de ML para poder auditar
    // despues si el LLM la siguio o se aparto de ella, y para tener un
    // historial real de aciertos del clasificador entrenado.
    senal_ml: senalMl,
  },
};

return [{
  json: {
    run_id: $json.run_id,
    recuerdo_id: $json.recuerdo_id,
    estado: $json.estado,
    bodyString: JSON.stringify(body),
  },
}];
